SELECT  FROM ifj_auth_user

    
        AND (LOWER(username) LIKE LOWER(#{namePattern}) ESCAPE '!'
            OR LOWER(display_name) LIKE LOWER(#{namePattern}) ESCAPE '!')
    
    AND role_code = #{role}
    AND enabled = #{enabled}

ORDER BY id

mapper.update:
UPDATE ifj_auth_user SET display_name = #{user.displayName}, revision = revision + 1,
    update_time = #{user.updateTime}
WHERE id = #{user.id} AND revision = #{expectedRevision} AND revision < 9223372036854775807

UPDATE ifj_auth_user SET role_code = #{user.roleCode}, enabled = #{user.enabled},
    security_version = security_version + 1, revision = revision + 1,
    update_time = #{user.updateTime}
WHERE id = #{user.id} AND revision = #{expectedRevision}
    AND revision < 9223372036854775807 AND security_version < 9223372036854775807

UPDATE ifj_auth_user SET password_hash = #{user.passwordHash},
    must_change_password = #{user.mustChangePassword},
    security_version = security_version + 1, revision = revision + 1,
    update_time = #{user.updateTime}
WHERE id = #{user.id} AND revision = #{expectedRevision}
    AND revision < 9223372036854775807 AND security_version < 9223372036854775807

UPDATE ifj_auth_user SET display_name = #{user.displayName,jdbcType=NVARCHAR}, revision = revision + 1,
    update_time = #{user.updateTime}
WHERE id = #{user.id} AND revision = #{expectedRevision} AND revision < 9223372036854775807

